  const protoShape = (schema: z.ZodType = z.string()) =>
    Object.fromEntries([
      ["__proto__", schema],
      ["name", z.string()],
    ]) as Record<string, any>;

  const expectStripped = (parsed: any) => {
    expect(Object.getPrototypeOf(parsed)).toBe(Object.prototype);
    expect(Object.prototype.hasOwnProperty.call(parsed, "__proto__")).toBe(false);
    expect(parsed).toEqual({ name: "alice" });
  };

  test("jit fastpass", () => {
    const schema = z.object(protoShape(z.object({ isAdmin: z.boolean() })));
    expect(Object.keys(schema.shape)).toEqual(["__proto__", "name"]);
    expectStripped(schema.parse(protoInput()));
  });

  test("jitless", () => {
    expectStripped(z.object(protoShape()).parse(protoInput(), { jitless: true } as any));
  });

  test("async", async () => {
    expectStripped(await z.object(protoShape(z.any().refine(async () => true))).parseAsync(protoInput()));
  });

  test("schema is not run: invalid, missing and defaulted values", () => {
    for (const jitless of [false, true]) {
      const ctx = { jitless } as any;
      expectStripped(z.object(protoShape()).parse(JSON.parse('{"__proto__":123,"name":"alice"}'), ctx));
      expectStripped(z.object(protoShape()).parse({ name: "alice" }, ctx));
      expectStripped(z.object(protoShape(z.string().default("fallback"))).parse({ name: "alice" }, ctx));
    }
  });

  test("an own getter is not invoked", () => {
    let reads = 0;
    const input = Object.defineProperty({ name: "alice" }, "__proto__", {
      get() {
        reads++;
        return "value";
      },
      enumerable: true,
    });
    for (const jitless of [false, true]) {
      expectStripped(z.object(protoShape()).parse(input, { jitless } as any));
    }
    expect(reads).toBe(0);
  });

  test("pick keeps a declared key in shape", () => {
    const mask = Object.fromEntries([["__proto__", true]]) as Record<string, true>;
    const picked = z.object(protoShape()).pick(mask);

    expect(Object.keys(picked.shape)).toEqual(["__proto__"]);
    expect(picked.parse(protoInput())).toEqual({});
    expect(() => z.object({ value: z.string() }).pick(mask as any).shape).toThrow('Unrecognized key: "__proto__"');
  });

  test.each(["omit", "partial", "required"] as const)("%s rejects an undeclared key", (method) => {
    const mask = Object.fromEntries([["__proto__", true]]);
    const schema = z.object({ value: z.string() });

    expect(() => (schema[method] as any)(mask).shape).toThrow('Unrecognized key: "__proto__"');
  });

